#include <vulkan/vulkan.h>
#include <stdio.h>
int main(void){ VkApplicationInfo a={.sType=VK_STRUCTURE_TYPE_APPLICATION_INFO,.apiVersion=VK_API_VERSION_1_1}; VkInstanceCreateInfo c={.sType=VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO,.pApplicationInfo=&a}; VkInstance i; if(vkCreateInstance(&c,0,&i))return 1; uint32_t n=1; VkPhysicalDevice d; vkEnumeratePhysicalDevices(i,&n,&d); VkPhysicalDeviceFeatures f; vkGetPhysicalDeviceFeatures(d,&f); printf("writeWithoutFormat=%u extendedFormats=%u\n",f.shaderStorageImageWriteWithoutFormat,f.shaderStorageImageExtendedFormats); VkFormat fs[]={VK_FORMAT_R8_UNORM,VK_FORMAT_R16_SFLOAT,VK_FORMAT_R32_SFLOAT}; const char *names[]={"R8_UNORM","R16_SFLOAT","R32_SFLOAT"}; for(unsigned k=0;k<3;k++){VkFormatProperties p;vkGetPhysicalDeviceFormatProperties(d,fs[k],&p);printf("%s optimal=0x%x storage=%d sampled=%d\n",names[k],p.optimalTilingFeatures,!!(p.optimalTilingFeatures&VK_FORMAT_FEATURE_STORAGE_IMAGE_BIT),!!(p.optimalTilingFeatures&VK_FORMAT_FEATURE_SAMPLED_IMAGE_BIT));}vkDestroyInstance(i,0);}
